files.content:
:root {
  --bg: #1e293b;
  --card-bg: #f8fafc;
  --text: #0f172a;
  --accent: #3b82f6;
  --accent-hover: #2563eb;
  --accent-pressed: #1d4ed8;
  --danger: #ef4444;
  --success: #22c55e;
  --border: #cbd5e1;
  --radius: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  color: var(--text);
}

.desk {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 24px;
  width: 100%;
  max-width: 600px;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.3);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 16px;
  text-align: center;
  color: var(--text);
}

.controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 20px;
}

.filter-label {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 1rem;
  cursor: pointer;
}

.filter-label input[type="checkbox"] {
  width: 18px;
  height: 18px;
  accent-color: var(--accent);
  cursor: pointer;
}

.count {
  font-weight: 600;
  color: var(--accent);
  background: #e0f2fe;
  padding: 4px 12px;
  border-radius: 999px;
  font-size: 0.95rem;
}

.book-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.book-item {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 12px 16px;
  background: white;
  border: 1px solid var(--border);
  border-radius: var(--radius);
}

.book-info {
  flex: 1 1 200px;
  min-width: 0;
}

.book-title {
  font-weight: 600;
  font-size: 1.05rem;
  margin-bottom: 2px;
  overflow-wrap: break-word;
}

.book-author {
  font-size: 0.9rem;
  color: #64748b;
}

.badge {
  display: inline-block;
  padding: 2px 10px;
  border-radius: 999px;
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.badge.available {
  background: #dcfce7;
  color: #166534;
}

.badge.checked-out {
  background: #fee2e2;
  color: #991b1b;
}

.btn {
  font-family: inherit;
  font-size: 0.95rem;
  font-weight: 600;
  padding: 8px 16px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  color: white;
  background: var(--accent);
  white-space: nowrap;
}

.btn:hover {
  background: var(--accent-hover);
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn:active {
  background: var(--accent-pressed);
  transform: scale(0.97);
}

.btn.return {
  background: var(--danger);
}

.btn.return:hover {
  background: #dc2626;
}

.btn.return:active {
  background: #b91c1c;
}

@media (max-width: 400px) {
  .desk {
    padding: 16px;
  }
  .book-item {
    flex-direction: column;
    align-items: stretch;
  }
  .btn {
    width: 100%;
    text-align: center;
  }
}

const books = [
  { id: 1, title: 'The Pragmatic Programmer', author: 'Hunt & Thomas', available: true },
  { id: 2, title: 'Clean Code', author: 'Robert C. Martin', available: false },
  { id: 3, title: 'JavaScript: The Good Parts', author: 'Douglas Crockford', available: true },
  { id: 4, title: 'You Don\'t Know JS', author: 'Kyle Simpson', available: true },
  { id: 5, title: 'Eloquent JavaScript', author: 'Marijn Haverbeke', available: false },
  { id: 6, title: 'Refactoring', author: 'Martin Fowler', available: true }
];

const bookList = document.getElementById('book-list');
const filterCheckbox = document.getElementById('filter-available');
const countDisplay = document.getElementById('checked-out-count');

function render() {
  const showAvailableOnly = filterCheckbox.checked;
  const visibleBooks = showAvailableOnly ? books.filter(b => b.available) : books;

  bookList.innerHTML = '';
  visibleBooks.forEach(book => {
    const li = document.createElement('li');
    li.className = 'book-item';

    const info = document.createElement('div');
    info.className = 'book-info';

    const title = document.createElement('div');
    title.className = 'book-title';
    title.textContent = book.title;

    const author = document.createElement('div');
    author.className = 'book-author';
    author.textContent = book.author;

    const badge = document.createElement('span');
    badge.className = 'badge ' + (book.available ? 'available' : 'checked-out');
    badge.textContent = book.available ? 'Available' : 'Checked out';

    info.appendChild(title);
    info.appendChild(author);
    info.appendChild(badge);

    const btn = document.createElement('button');
    btn.className = 'btn' + (book.available ? '' : ' return');
    btn.textContent = book.available ? 'Check out' : 'Return';
    btn.setAttribute('aria-label', (book.available ? 'Check out ' : 'Return ') + book.title);
    btn.addEventListener('click', () => {
      book.available = !book.available;
      render();
    });

    li.appendChild(info);
    li.appendChild(btn);
    bookList.appendChild(li);
  });

  const checkedOutCount = books.filter(b => !b.available).length;
  countDisplay.textContent = checkedOutCount + ' checked out';
}

filterCheckbox.addEventListener('change', render);

render();
